SELECT DATE_TRUNC('WEEK', opened_date) AS week_start, region, SUM(sqft) FILTER (WHERE city = 'Singapore') AS singapore_total_sqft, MIN(sqft) AS min_sqft, COUNT_IF(city = 'Chiang Mai') AS chiang_mai_events, SUM(CASE WHEN city = 'Bangkok' THEN sqft ELSE 0 END) AS bangkok_sqft, COUNT(*) FILTER (WHERE region = 'North') AS north_rows, GROUPING(DATE_TRUNC('WEEK', opened_date)) AS grouping_id FROM stores GROUP BY GROUPING SETS ((DATE_TRUNC('WEEK', opened_date), region), (DATE_TRUNC('WEEK', opened_date)))
